/**
 * Typed access to shared/catalog.json (generated by scripts/build-catalog.mjs from sources/).
 * FROZEN: owned by the lead (graph.md → N1). Erasable syntax only.
 *
 * Provenance matters here. Datasets marked 'demo' are illustrative figures carried over from
 * the original prototypes — they are not measurements, holdings, balances or market data, and
 * the UI must present them as such (see `isDemo`).
 */
import raw from './catalog.json' with { type: 'json' };

export type DatasetProvenance = 'config' | 'demo';

export interface DatasetMeta {
  provenance: DatasetProvenance;
  from: string[];
  demoFields?: string[];
}

export interface Platform { id: string; name: string; icon: string; color: string }
export interface Sector { id: string; icon: string; label: string; market: string; sharePct: number | null }
export interface MediaType { id: string; label: string; icon: string; duration: string }
export interface PipelineAgent { id: string; name: string; icon: string; color: string; role: string }
export interface InvestorProfile { id: string; name: string; budget: string; interestPct: number; flag: string; priority: string }
export interface OfferTier { id: string; tier: string; price: number; bonus: string; perks: string[]; color: string }
export interface TreeNodeData { name: string; code: string; earnings: number; level: number; children: TreeNodeData[] }
export interface LabelValueColor { label: string; value: string; color: string }
export interface CommissionLevel { level: string; rate: string; note: string }
export interface Division {
  id: string; name: string; title: string; color: string;
  agents: { name: string; icon: string; desc: string; status: string }[];
  tools: string[];
}
export interface DashboardStat { label: string; value: string; delta: string; icon: string; color: string }
export interface BugRecord { id: string; sev: string; area: string; desc: string; fix: string; fixed: boolean }
export interface QuickAction { label: string; icon: string; target: string; color: string }
export interface Angel { id: string; name: string; en: string; icon: string; role: string; color: string }
export interface SovereignLayer { id: number; icon: string; label: string; labelAr: string; color: string; metrics: Record<string, string>; desc: string }
export interface BootLogLine { t: string; msg: string; color: string }
export interface TokenAllocation { label: string; pct: number; color: string }
export interface Product { id: number; name: string; cat: string; price: number; shn: number; rating: number; reviews: number; emoji: string; badge: string; desc: string }
export interface Proposal { id: number; title: string; status: string; for: number; against: number; quorum: number; ends: string; cat: string }
export interface WalletTransaction { type: string; amt: string; shn: string; time: string; color: string }
export interface DemoPayout { label: string; value: string; when: string; color: string }

export interface Catalog {
  themes: { superapp: Record<string, string | number>; nexus: Record<string, string>; greenMedia: Record<string, string> };
  platforms: Platform[];
  campaignGoals: string[];
  campaignTones: string[];
  sectors: Sector[];
  mediaTypes: MediaType[];
  pipelineAgents: PipelineAgent[];
  investorProfiles: InvestorProfile[];
  offerTiers: OfferTier[];
  referralTree: TreeNodeData;
  treeStats: LabelValueColor[];
  commissionLevels: CommissionLevel[];
  referralSteps: { icon: string; text: string }[];
  referralCode: string;
  divisions: Division[];
  dashboardStats: DashboardStat[];
  orgSummary: { value: string; label: string }[];
  bugRegistry: BugRecord[];
  engineerSuggestions: string[];
  quickActions: QuickAction[];
  angels: Angel[];
  layers: SovereignLayer[];
  sovereignSummary: LabelValueColor[];
  sovereignBootLog: BootLogLine[];
  tokenAllocation: TokenAllocation[];
  contractInfo: { label: string; value: string }[];
  products: Product[];
  productCategories: string[];
  proposals: Proposal[];
  proposalStatusColors: Record<string, string>;
  newsTicker: string[];
  walletActions: { label: string; icon: string }[];
  walletTokenStats: LabelValueColor[];
  walletTransactions: WalletTransaction[];
  bankOptions: string[];
  bankFormSteps: string[];
  demoPayouts: DemoPayout[];
}

export type DatasetKey = keyof Catalog;

export const catalog = raw.data as unknown as Catalog;
export const catalogMeta = raw.meta as unknown as Record<DatasetKey, DatasetMeta>;

/** True when the dataset is illustrative and must be shown with a demo marker. */
export function isDemo(key: DatasetKey): boolean {
  return catalogMeta[key].provenance === 'demo';
}

export const DATASET_KEYS = Object.keys(raw.data) as DatasetKey[];
